RENDERERS.managers = () => {
  const list = CS.standings.map(s => managerById[s.managerId]).filter(Boolean);
  Object.values(managerById).forEach(m => { if (!list.includes(m)) list.push(m); });
  return `
    ${pageHead("managers", `${list.length} clubs · ${D.metadata.cities.length} cities`, "Managers", "Tap a club to open the full dossier.")}
    <div class="mgr-grid">${list.map(m => {
      const s = standingById[m.id];
      const c = m.careerRecord || {};
      return `<button class="card mgr-card" data-mgr="${m.id}" style="--c:${m.color}">
        <span class="mgr-band"></span>
        <span class="mgr-body">
          <span class="mgr-top">${crest(m)}<span style="min-width:0"><span class="mgr-team" style="display:block">${esc(m.teamName)}${trophyBadge(m)}</span><span class="mgr-name" style="display:block">${esc(m.name)} · ${esc(m.city)}</span></span>
            ${s ? `<span class="phone-only mgr-form">${formPills(s.form)}</span>` : ""}
            ${s ? `<span class="mgr-rank"><b>${ordinal(s.rank)}</b><small>${s.pts} PTS</small></span>` : ""}</span>
          <span style="display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap">
            <span class="chip ${/Commissioner/.test(m.role) ? "accent" : ""}">${esc(m.role)}</span>
            ${s ? formPills(s.form) : ""}
          </span>
          ${m.accolades && m.accolades.length ? `<span class="trophies">${m.accolades.map(a => `<span class="chip cup">🏆 ${esc(a)}</span>`).join("")}</span>` : ""}
          <span class="mgr-stats">
            <span><small>Career</small><b class="num">${c.w ?? 0}-${c.d ?? 0}-${c.l ?? 0}</b></span>
            <span><small>Pts / wk</small><b class="num">${c.ppg != null ? fmt(c.ppg, 2) : "–"}</b></span>
            <span><small>Winnings</small><b class="num">${money(m.careerMoney || 0)}</b></span>
          </span>
        </span>
      </button>`;
    }).join("")}</div>`;
};

// Accolades also cover things like "New Manager", so only count the silverware.
function trophyBadge(m) {
  const n = (m.accolades || []).filter(a => /Champion|Winner/i.test(a)).length;
  return n ? `<span class="phone-only mgr-cups" aria-label="${n} ${n > 1 ? "trophies" : "trophy"}">🏆${n > 1 ? n : ""}</span>` : "";
}

function openManager(id) {
  const m = managerById[id];
  if (!m) return;
  const s = standingById[id];
  const c = m.careerRecord || {};
  const fixtures = [];
  for (let gw = 1; gw <= TOTAL_GW; gw++) {
    matchesFor(gw).forEach(x => {
      if (x.home !== m.name && x.away !== m.name) return;
      const home = x.home === m.name;
      fixtures.push({ gw, comp: x.competition, stage: x.tournamentStage, opp: home ? x.away : x.home, oppTeam: home ? x.awayTeam : x.homeTeam, us: home ? x.homeScore : x.awayScore, them: home ? x.awayScore : x.homeScore, played: isFinal(x), live: x.status === "Live", home, match: x });
    });
  }
  const played = fixtures.filter(f => f.played);
  const upcoming = fixtures.filter(f => !f.played).slice(0, 5);
  const fixtureRow = f => {
    const r = f.played ? (f.us > f.them ? "W" : f.us < f.them ? "L" : "D") : "";
    const cm = compMeta(f.comp);
    return `<div class="fixture" ${matchAttr(f.match)}><span class="gw">GW ${f.gw}</span>${crest(f.opp, "sm")}<span style="min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${f.home ? "vs" : "@"} <b>${esc(f.oppTeam)}</b>${cm.cls ? ` <span class="chip ${cm.cls}" style="padding:0 7px;font-size:10.5px">${cm.cls === "cl" ? "UCL" : "Cup"}</span>` : ""}</span>
      ${f.played ? `<span style="display:flex;gap:8px;align-items:center"><span class="num">${fmtPts(f.us)} – ${fmtPts(f.them)}</span><span class="f-pill f-${r}">${r}</span></span>`
        : f.live ? `<span style="display:flex;gap:8px;align-items:center;font-size:12.5px"><span class="num">${fmtPts(f.us)} – ${fmtPts(f.them)}</span>${LIVE_LABEL}</span>`
        : `<span class="dim" style="font-size:12.5px">Scheduled</span>`}</div>`;
  };

  $("#mgr-modal").style.setProperty("--c", m.color);
  $("#mgr-modal").innerHTML = `
    <div class="modal-hero">
      ${crest(m, "lg")}
      <div style="min-width:0">
        <div class="eyebrow" style="margin-bottom:2px">${esc(m.role)}</div>
        <h2 class="display modal-title" style="margin:0;font-size:36px">${esc(m.teamName)}</h2>
        <div class="muted">${esc(m.name)} · ${esc(m.city)}</div>
      </div>
      <button class="icon-btn modal-close" data-close aria-label="Close">${ICON.close}</button>
    </div>
    <div class="modal-body">
      ${m.bio ? `<p class="modal-bio" style="margin:0;color:var(--text-2);font-size:15px">${esc(m.bio)}</p>` : ""}
      ${m.accolades && m.accolades.length ? `<div class="trophies">${m.accolades.map(a => `<span class="chip cup">🏆 ${esc(a)}</span>`).join("")}</div>` : ""}
      ${s ? `<div class="modal-section"><h4>This season</h4><div class="kv-grid">
        <div class="kv"><small>Position</small><b>${ordinal(s.rank)}</b></div>
        <div class="kv"><small>Points</small><b>${s.pts}</b></div>
        <div class="kv"><small>Points for</small><b>${fmtPts(s.pf)}</b></div>
        <div class="kv"><small>Efficiency</small><b>${fmt(s.eff, 1)}%</b></div>
      </div></div>` : ""}
      <div class="modal-section"><h4>Career</h4><div class="kv-grid">
        <div class="kv"><small>Record</small><b>${c.w ?? 0}-${c.d ?? 0}-${c.l ?? 0}</b></div>
        <div class="kv"><small>Pts / week</small><b>${c.ppg != null ? fmt(c.ppg, 2) : "–"}</b></div>
        <div class="kv"><small>Weeks</small><b>${c.weeks ?? 0}</b></div>
        <div class="kv"><small>Winnings</small><b>${money(m.careerMoney || 0)}</b></div>
      </div></div>
      ${m.teamId ? `<div class="modal-section mgr-squad"><h4>Current squad</h4><div id="squad-list">${skeletonRows(6)}</div></div>` : ""}
      ${played.length ? `<div class="modal-section mgr-results"><h4>Results</h4><div class="fixture-list">${played.map(fixtureRow).join("")}</div></div>` : ""}
      ${upcoming.length ? `<div class="modal-section mgr-next"><h4>Next up</h4><div class="fixture-list">${upcoming.map(fixtureRow).join("")}</div></div>` : ""}
    </div>`;
  openOverlay("#mgr-overlay");
  if (m.teamId) loadSquad(m.teamId);
}

/* ==========================================================================
   LINEUPS (matchup view and current squad, loaded from the hub server on demand)
   ========================================================================== */

const POS_ORDER = ["G", "D", "M", "F"];
const POS_NAMES = { G: "Goalkeeper", D: "Defenders", M: "Midfielders", F: "Forwards" };
const LINEUP_API_HELP = "Lineups come from Fantrax through the hub server, so they only load when the site runs on app.py (locally or on Render).";

function skeletonRows(n) { return Array.from({ length: n }, () => `<div class="skeleton"></div>`).join(""); }

// "COV 1 @TOT 3 F" -> "COV 1–3 TOT"; anything else (e.g. an upcoming kickoff) is shown as Fantrax sends it.
function prettyGame(game) {
  const m = String(game || "").match(/^([A-Z]{2,4}) (\d+) @([A-Z]{2,4}) (\d+)/);
  return m ? `${m[1]} ${m[2]}–${m[4]} ${m[3]}` : String(game || "").replace(/@/g, "@ ");
}

async function fetchJson(url) {
  const res = await fetch(url, { headers: { Accept: "application/json" } });
  const body = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(body.error || `HTTP ${res.status}`);
  return body;
}

// Predictions are per minute, so the points depend on how long a player is on. Clean sheet points only
// count from 60 minutes (fantrax_wrapper/predictions.py). The minutes someone picks last until a reload.
const PRED_MINUTE_OPTIONS = [15, 30, 45, 60, 75, 90];
const CLEAN_SHEET_MINUTES = 60;
const predMinutesPicked = new Map();

function predictedPoints(pr, minutesPerGame) {
  return pr.games * (pr.per_min * minutesPerGame + (minutesPerGame >= CLEAN_SHEET_MINUTES ? pr.clean_sheet : 0));
}
function predLabel(pr, minutesPerGame, compact = false, adjusted = false) {
  const points = fmt(predictedPoints(pr, minutesPerGame), 1);
  if (!compact) return `Pred ${points} · ${fmt(minutesPerGame * pr.games)}′`;
  if (adjusted) return `${points} · ${fmt(minutesPerGame * pr.games)}′`;
  return minutesPerGame ? points : "–";
}
// A finished gameweek defaults to the minutes actually played, anything else to a full game.
function predDefaultMinutes(p, final) { return final ? p.minutes / p.prediction.games : 90; }

// Predicted team totals: each team's starters by gameweek, added up with whatever minutes have been picked.
const predictedStarters = {};
const predictedLoads = {};

function teamPredictedTotal(gw, teamId, final) {
  const starters = (predictedStarters[gw] || {})[teamId] || [];
  const predicted = starters.filter(p => p.prediction);
  if (!predicted.length) return null;
  return predicted.reduce((total, p) => total + predictedPoints(p.prediction, predMinutesPicked.get(`${gw}:${p.id}`) ?? predDefaultMinutes(p, final)), 0);
}
function predictedTotalTag(gw, teamId, final, plain = false) {
  return `<span class="pred-total" data-pred-total="${gw}|${esc(teamId || "")}" data-final="${final ? 1 : 0}" ${plain ? "data-plain" : ""}></span>`;
}
function predictedScoreline(m) {
  const final = isFinal(m);
  return `<small class="lu-pred" hidden>${predictedTotalTag(m.gw, teamIdByName[m.homeTeam], final, true)}${predictedTotalTag(m.gw, teamIdByName[m.awayTeam], final, true)}</small>`;
}
const PRED_NOTES = {
  cards: {
    upcoming: "Predicted totals assume every starter plays 90 minutes. Open a match and click any prediction to change a player's minutes.",
    final: "Predicted totals use the minutes each player actually played. Open a match and click any prediction to try different minutes.",
  },
  cardsPhone: {
    upcoming: "Pred assumes 90 minutes per starter. Open a match to change it.",
    final: "Pred uses actual minutes. Open a match to change it.",
  },
  lineup: {
    upcoming: "Predictions assume each player plays 90 minutes. Click a prediction to change a player's minutes.",
    final: "Predictions use the minutes each player actually played. Click a prediction to try different minutes.",
  },
  board: {
    upcoming: "Predictions assume 90 minutes. Tap one to change it.",
    final: "Predictions use actual minutes. Tap one to change it.",
  },
};
function predictionNote(gw, final, kind) {
  const key = final ? "final" : "upcoming";
  const text = kind === "cards" ? phoneLabel(PRED_NOTES.cards[key], PRED_NOTES.cardsPhone[key]) : PRED_NOTES[kind][key];
  return `<p class="pred-note" data-pred-note="${gw}" hidden>${text}</p>`;
}
function refreshPredictedTotals() {
  $$("[data-pred-total]").forEach(el => {
    const [gw, teamId] = el.dataset.predTotal.split("|");
    const total = teamPredictedTotal(gw, teamId, el.dataset.final === "1");
    el.textContent = total == null ? "" : `${"plain" in el.dataset ? "" : "Pred "}${fmt(total, 1)}`;
  });
  $$(".lu-pred").forEach(el => { el.hidden = [...el.querySelectorAll("[data-pred-total]")].some(t => !t.textContent); });
  $$("[data-pred-note]").forEach(el => {
    const hasPredictions = Object.values(predictedStarters[el.dataset.predNote] || {}).some(starters => starters.some(p => p.prediction));
    el.hidden = !hasPredictions;
    const box = el.closest("[data-pred-only]");
    if (box) box.hidden = !hasPredictions;
  });
}
function loadPredictedTotals() {
  const gws = new Set([...$$("[data-pred-total]")].map(el => el.dataset.predTotal.split("|")[0]));
  const teams = D.managers.map(m => encodeURIComponent(m.teamId)).join(",");
  gws.forEach(gw => {
    predictedLoads[gw] = predictedLoads[gw] || fetchJson(`/api/predicted-totals/${gw}?teams=${teams}`)
      .then(data => { predictedStarters[gw] = { ...data.teams, ...predictedStarters[gw] }; })
      .catch(() => {}); // the cards still work without totals
    predictedLoads[gw].then(refreshPredictedTotals);
  });
  refreshPredictedTotals();
}

function predictionControl(p, gw, final, compact = false) {
  const pr = p.prediction;
  const key = `${gw}:${p.id}`;
  const picked = predMinutesPicked.get(key);
  const minutes = picked ?? predDefaultMinutes(p, final);
  const adjusted = picked != null && picked !== predDefaultMinutes(p, final);
  return `<button type="button" class="pred ${adjusted ? "adjusted" : ""}" ${compact ? "data-compact" : ""} data-pred="${esc(key)}" data-per-min="${pr.per_min}" data-clean-sheet="${pr.clean_sheet}" data-games="${pr.games}" data-default="${predDefaultMinutes(p, final)}" aria-expanded="false" title="${pr.basis === "player" ? "Predicted points at these minutes." : "No minutes this season, so this is how the position has done" + (pr.basis === "position_vs_opponent" ? " against this opponent." : " overall.")} Click to change the minutes.">${predLabel(pr, minutes, compact, adjusted)}</button>`;
}
function predictionPicker(p, gw, final, label = "Minutes") {
  const key = `${gw}:${p.id}`;
  const picked = predMinutesPicked.get(key);
  const option = (value, label) => `<button type="button" data-pred-minutes="${value}" aria-pressed="${(picked ?? null) === (value === "default" ? null : value)}">${label}</button>`;
  return `<div class="pred-picker" data-pred-picker="${esc(key)}" hidden><span class="pred-picker-label">${esc(label)}</span>${PRED_MINUTE_OPTIONS.map(m => option(m, `${m}`)).join("")}${option("default", final ? "Actual" : "Reset")}</div>`;
}

document.addEventListener("click", e => {
  const toggle = e.target.closest("[data-pred]");
  if (toggle) {
    const picker = document.querySelector(`[data-pred-picker="${CSS.escape(toggle.dataset.pred)}"]`);
    const opening = picker.hidden;
    document.querySelectorAll("[data-pred-picker]").forEach(el => { el.hidden = true; });
    document.querySelectorAll("[data-pred]").forEach(el => el.setAttribute("aria-expanded", "false"));
    picker.hidden = !opening;
    toggle.setAttribute("aria-expanded", String(opening));
    return;
  }
  const choice = e.target.closest("[data-pred-minutes]");
  if (!choice) return;
  const picker = choice.closest("[data-pred-picker]");
  const key = picker.dataset.predPicker;
  const button = document.querySelector(`[data-pred="${CSS.escape(key)}"]`);
  const value = choice.dataset.predMinutes;
  if (value === "default") predMinutesPicked.delete(key); else predMinutesPicked.set(key, +value);
  const { perMin, cleanSheet, games, default: fallback } = button.dataset;
  const pr = { per_min: +perMin, clean_sheet: +cleanSheet, games: +games };
  const adjusted = value !== "default" && +value !== +fallback;
  button.textContent = predLabel(pr, value === "default" ? +fallback : +value, "compact" in button.dataset, adjusted);
  button.classList.toggle("adjusted", adjusted);
  picker.querySelectorAll("[data-pred-minutes]").forEach(el => el.setAttribute("aria-pressed", String(el === choice && value !== "default")));
  picker.hidden = true;
  button.setAttribute("aria-expanded", "false");
  button.focus();
  refreshPredictedTotals();
});

function playerRow(p, { bench = false, star = false, showSeason = false, gw = null, final = false } = {}) {
  const pos = p.slot || (p.positions || "").split(",")[0] || "–";
  const meta = showSeason
    ? [p.club, p.positions && p.positions.replace(/,/g, "/"), `${p.games_played} GP`].filter(Boolean).join(" · ")
    : [p.club, p.game && prettyGame(p.game), p.minutes ? `${p.minutes}′` : (p.game ? "DNP" : "")].filter(Boolean).join(" · ");
  return `<div class="lu-row ${bench ? "bench" : ""}">
    <span class="pos-tag" title="${esc(POS_NAMES[pos] || pos)}">${esc(pos)}</span>
    <span style="min-width:0"><span class="nm" style="display:block">${esc(p.name)}${star ? `<span class="star" title="Top scorer in this matchup">★</span>` : ""}</span><span class="meta" style="display:block">${esc(meta)}</span></span>
    <span class="pts-cell"><span class="pts ${p.points < 0 ? "neg" : ""}">${fmtPts(p.points)}</span>${p.prediction ? predictionControl(p, gw, final) : ""}</span>
  </div>${p.prediction ? predictionPicker(p, gw, final) : ""}`;
}

function lineupColumn(lu, starId, gw, final) {
  if (!lu) return `<div class="lu-col"><div class="empty">No lineup returned</div></div>`;
  const benchPts = lu.bench.reduce((t, p) => t + p.points, 0);
  return `<div class="lu-col">
    <div class="lu-section"><span>Starting XI</span><span>Pts</span></div>
    ${lu.starters.map(p => playerRow(p, { star: p.id === starId, gw, final })).join("")}
    <div class="lu-total"><span>Starters total</span><span class="score-cell"><b class="num">${fmtPts(lu.total)}</b>${predictedTotalTag(gw, lu.team_id, final)}</span></div>
    <div class="lu-section"><span>Bench</span><span>Pts</span></div>
    ${lu.bench.length ? lu.bench.map(p => playerRow(p, { bench: true, gw, final })).join("") : `<div class="dim" style="font-size:13px">Empty</div>`}
    <div class="lu-total"><span>Left on the bench</span><b class="num">${fmtPts(benchPts)}</b></div>
    ${lu.injured_reserve.length ? `<div class="lu-section"><span>Injured reserve</span><span></span></div>${lu.injured_reserve.map(p => playerRow(p, { bench: true, gw, final })).join("")}` : ""}
  </div>`;
}

// On a phone, both lineups share one board: players at each position face each other across a centre
// column, so a matchup can be read row by row without scrolling past one team to reach the other.
const phoneLayout = window.matchMedia("(max-width: 560px)");
const POSITION_ORDER = ["G", "D", "M", "F"];

function shortPlayerName(name) {
  const parts = String(name).trim().split(/\s+/);
  return parts.length > 1 ? `${parts[0][0]}. ${parts.slice(1).join(" ")}` : parts[0];
}
function boardPosition(p) { return p.slot || (p.positions || "").split(",")[0] || ""; }

function pairByPosition(home, away) {
  const inPosition = (players, pos) => players.filter(p => boardPosition(p) === pos);
  const others = players => players.filter(p => !POSITION_ORDER.includes(boardPosition(p)));
  const rows = [];
  [...POSITION_ORDER, ""].forEach(pos => {
    const h = pos ? inPosition(home, pos) : others(home);
    const a = pos ? inPosition(away, pos) : others(away);
    for (let i = 0; i < Math.max(h.length, a.length); i++) rows.push({ pos, home: h[i], away: a[i] });
  });
  return rows;
}

function boardFixture(p, played) {
  if (!p.game) return p.club || "";
  if (!played) return [p.club, prettyGame(p.game.split(" ")[0])].join(" · ");
  return [prettyGame(p.game), p.minutes ? `${p.minutes}′` : "DNP"].join(" · ");
}

function boardPlayer(p, side, m, starId) {
  if (!p) return `<div class="mu-player ${side}"></div>`;
  const played = hasScore(m), final = isFinal(m);
  const score = played ? `<span class="mu-pts ${p.points < 0 ? "neg" : ""}">${fmtPts(p.points)}</span>` : "";
  const prediction = p.prediction ? predictionControl(p, m.gw, final, true) : "";
  return `<div class="mu-player ${side}">
    <span class="mu-name">${esc(shortPlayerName(p.name))}${p.id === starId ? `<span class="star" title="Top scorer in this matchup">★</span>` : ""}</span>
    <span class="mu-value">${played ? score : prediction}</span>
    <span class="mu-fixture">${esc(boardFixture(p, played))}</span>
    <span class="mu-value">${played ? prediction : ""}</span>
  </div>`;
}

function boardRows(home, away, m, starId) {
  return pairByPosition(home, away).map(row => {
    const pickers = [row.home, row.away].filter(p => p && p.prediction).map(p => predictionPicker(p, m.gw, isFinal(m), `${shortPlayerName(p.name)} minutes`)).join("");
    return `<div class="mu-row">${boardPlayer(row.home, "home", m, starId)}<span class="mu-pos" title="${esc(POS_NAMES[row.pos] || "")}">${esc(row.pos)}</span>${boardPlayer(row.away, "away", m, starId)}</div>${pickers}`;
  }).join("");
}

function matchupBoard(hl, al, m, starId) {
  const home = hl || { starters: [], bench: [], injured_reserve: [] };
  const away = al || { starters: [], bench: [], injured_reserve: [] };
  const benchPoints = lineup => fmtPts(lineup.bench.reduce((t, p) => t + p.points, 0));
  const reserve = home.injured_reserve.length || away.injured_reserve.length;
  return `<div class="mu-board">
    ${boardRows(home.starters, away.starters, m, starId)}
    <div class="mu-section">${hasScore(m) ? `<b class="num">${benchPoints(home)}</b>` : "<b></b>"}<span>Bench</span>${hasScore(m) ? `<b class="num">${benchPoints(away)}</b>` : "<b></b>"}</div>
    ${boardRows(home.bench, away.bench, m, null)}
    ${reserve ? `<div class="mu-section"><b></b><span>Injured reserve</span><b></b></div>${boardRows(home.injured_reserve, away.injured_reserve, m, null)}` : ""}
  </div>`;
}

function boardTeam(name, team, score, side, m) {
  const final = isFinal(m), played = hasScore(m);
  const total = predictedTotalTag(m.gw, teamIdByName[team], final, true);
  return `<div class="mu-team ${side}">
    <div class="mu-club">${crest(name, "sm")}<div class="mu-club-text"><div class="team">${esc(team)}</div><div class="mgr">${esc(name)}</div></div></div>
    <div class="mu-score">${played ? `<b class="num">${fmtPts(score)}</b><small class="mu-pred-total">Pred ${total}</small>` : `<b class="num">${total}</b><small class="mu-pred-total">Predicted</small>`}</div>
  </div>`;
}

let openMatch = null;
phoneLayout.addEventListener("change", () => {
  rerender();
  if (openMatch && $("#match-overlay").classList.contains("open")) openMatchup(openMatch);
});

async function openMatchup(m) {
  closeOverlays();
  openMatch = m;
  const onPhone = phoneLayout.matches;
  const final = isFinal(m), live = m.status === "Live";
  const hId = teamIdByName[m.homeTeam], aId = teamIdByName[m.awayTeam];
  const c = compMeta(m.competition);
  const side = (name, team, cls) => `<div class="side ${cls}">${cls === "away" ? "" : crest(name, "lg")}<div style="min-width:0"><div class="team">${esc(team)}</div><div class="mgr">${esc(name)}</div></div>${cls === "away" ? crest(name, "lg") : ""}</div>`;
  const note = final ? "" : live ? `${LIVE_LABEL.replace("Live", "Live scores. Points can still change until the gameweek officially ends.")}` : "These are the lineups currently set. Managers can change them until each player's match kicks off.";
  const boardHead = () => `
    <div class="mu-head">
      <div class="mu-title"><span>GW ${m.gw} · ${esc(m.tournamentStage || c.label)}</span><button class="icon-btn modal-close" data-close aria-label="Close">${ICON.close}</button></div>
      <div class="mu-teams">${boardTeam(m.home, m.homeTeam, m.homeScore, "home", m)}${boardTeam(m.away, m.awayTeam, m.awayScore, "away", m)}</div>
    </div>`;
  $("#match-modal").innerHTML = onPhone ? `${boardHead()}
    <div class="lu-note" ${live ? "" : "data-pred-only hidden"}>${live ? note : ""}${predictionNote(m.gw, final, "board")}</div>
    <div class="lu-grid" id="lu-grid"><div class="lu-col">${skeletonRows(11)}</div><div class="lu-col">${skeletonRows(11)}</div></div>` : `
    <div class="lu-head">
      ${side(m.home, m.homeTeam, "home")}
      <div class="lu-score"><b class="num">${hasScore(m) ? `${fmtPts(m.homeScore)} – ${fmtPts(m.awayScore)}` : "vs"}</b><small>GW ${m.gw} · ${esc(m.tournamentStage || c.label)}</small>${predictedScoreline(m)}</div>
      ${side(m.away, m.awayTeam, "away")}
      <button class="icon-btn modal-close" data-close aria-label="Close">${ICON.close}</button>
    </div>
    <div class="lu-note" ${note ? "" : "data-pred-only hidden"}>${note}${predictionNote(m.gw, final, "lineup")}</div>
    <div class="lu-grid" id="lu-grid"><div class="lu-col">${skeletonRows(11)}</div><div class="lu-col">${skeletonRows(11)}</div></div>`;
  openOverlay("#match-overlay");

  const grid = $("#lu-grid");
  if (!hId || !aId) { grid.innerHTML = `<div class="lu-col"><div class="empty">No Fantrax team id for this matchup. Re-run the sync.</div></div>`; return; }
  try {
    const data = await fetchJson(`/api/lineups/${m.gw}?teams=${encodeURIComponent(hId)},${encodeURIComponent(aId)}`);
    const hl = data.lineups[hId], al = data.lineups[aId];
    const starters = [...(hl ? hl.starters : []), ...(al ? al.starters : [])];
    const top = starters.length && hasScore(m) ? starters.reduce((b, p) => (p.points > b.points ? p : b)) : null;
    if (grid.isConnected) grid.innerHTML = onPhone ? matchupBoard(hl, al, m, top && top.id) : lineupColumn(hl, top && top.id, m.gw, final) + lineupColumn(al, top && top.id, m.gw, final);
    predictedStarters[m.gw] = { ...predictedStarters[m.gw], [hId]: hl ? hl.starters : [], [aId]: al ? al.starters : [] };
    refreshPredictedTotals();
  } catch (err) {
    if (grid.isConnected) grid.innerHTML = `<div class="lu-col" style="grid-column:1/-1"><div class="empty">Couldn't load lineups (${esc(err.message)}).<br>${esc(LINEUP_API_HELP)}</div></div>`;
  }
}

async function loadSquad(teamId) {
  const box = () => $("#squad-list");
  try {
    const data = await fetchJson(`/api/squad/${encodeURIComponent(teamId)}`);
    const groups = [["starter", "Starting XI"], ["bench", "Bench"], ["injured_reserve", "Injured reserve"]];
    const html = groups.map(([key, label]) => {
      const ps = data.players.filter(p => p.status === key);
      return ps.length ? `<div class="lu-section"><span>${label}</span><span>Season pts</span></div>${ps.map(p => playerRow(p, { bench: key !== "starter", showSeason: true })).join("")}` : "";
    }).join("");
    if (box()) box().innerHTML = html || `<div class="dim">No players returned.</div>`;
  } catch (err) {
    if (box()) box().innerHTML = `<div class="empty">Couldn't load the squad (${esc(err.message)}).<br>${esc(LINEUP_API_HELP)}</div>`;
  }
}

document.addEventListener("click", e => {
  const el = e.target.closest("[data-match]");
  if (!el || e.target.closest("[data-mgr]")) return;
  const m = findMatch(el.dataset.match);
  if (m) openMatchup(m);
});
document.addEventListener("keydown", e => {
  if (e.key !== "Enter" && e.key !== " ") return;
  const el = e.target.closest && e.target.closest("[data-match]");
  if (!el || el !== e.target) return;
  e.preventDefault();
  const m = findMatch(el.dataset.match);
  if (m) openMatchup(m);
});

